@Component("salaryComponent-handler")
@ProcessingGroup("salaryComponent-processing-group")
public class SalaryComponentEventHandler {
	
	// core constructor
	SalaryComponentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateSalaryComponentEvent
     */
    @EventHandler
    public void handle( CreateSalaryComponentEvent event) {
        entityManager.persist(new SalaryComponent(event.getSalaryComponentId(), event.getAmount(), event.getRecurring(), event.getCompensationPackage(), event.getComponentType()));
    }

    /*
     * @param	event UpdateSalaryComponentEvent
     */
    @EventHandler
    public SalaryComponent handle( UpdateSalaryComponentEvent event) {
    	entityManager.merge(new SalaryComponent(event.getSalaryComponentId(), event.getAmount(), event.getRecurring(), event.getCompensationPackage(), event.getComponentType()));
    }
    
    /*
     * @param	event DeleteSalaryComponentEvent
     */
    @EventHandler
    public void on( DeleteSalaryComponentEvent event) {
    	SalaryComponent entity = new SalaryComponent();
   
    	// ------------------------------------------
    	// apply the SalaryComponentId
    	// ------------------------------------------
    	entity.setSalaryComponentId( event.getSalaryComponentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final SalaryComponentRepository salaryComponentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(SalaryComponentEventHandler.class.getName());

}
